/**
 * Database connection: opens the file, applies pragmas, runs migrations.
 *
 * Nothing else in the app opens SQLite — the pull/sync logic and the read
 * queries both take the handle this module hands out.
 */
import { Database } from 'bun:sqlite';
import { drizzle, type BunSQLiteDatabase } from 'drizzle-orm/bun-sqlite';
import { migrate } from 'drizzle-orm/bun-sqlite/migrator';
import { mkdirSync } from 'node:fs';
import { dirname, join } from 'node:path';
import * as schema from './schema';

export type Db = BunSQLiteDatabase<typeof schema>;

/** Generated by `bun run db:generate`, committed, applied on every startup. */
const MIGRATIONS_FOLDER = join(import.meta.dir, '../../drizzle');

/**
 * Opens (and creates, if needed) the database at `path`, then migrates it.
 * Pass `:memory:` for tests.
 *
 * WAL lets the board keep reading while a pull writes; foreign keys are off by
 * default in SQLite and have to be turned on per connection.
 */
export function openDatabase(path: string): { db: Db; sqlite: Database } {
  if (path !== ':memory:') mkdirSync(dirname(path), { recursive: true });

  const sqlite = new Database(path, { create: true });
  sqlite.exec('PRAGMA journal_mode = WAL;');
  sqlite.exec('PRAGMA foreign_keys = ON;');

  const db = drizzle({ client: sqlite, schema });
  migrate(db, { migrationsFolder: MIGRATIONS_FOLDER });

  return { db, sqlite };
}
